package cl.robermotos.config;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;
@Component @ConfigurationProperties(prefix="delivery") public class DeliveryProperties { public String country="CL",currency="CLP"; public long quoteTimeoutMs=2500,quoteTtlSeconds=600; public boolean mockEnabled=true,simulateNoRiders=false; public Pickup pickup=new Pickup(); public Uber uber=new Uber(); public static class Pickup { public String name,phone,address; public double latitude,longitude; } public static class Uber { public boolean enabled; public String baseUrl,authUrl,clientId,clientSecret,customerId; } public String getCountry(){return country;} public void setCountry(String v){country=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;} public long getQuoteTimeoutMs(){return quoteTimeoutMs;} public void setQuoteTimeoutMs(long v){quoteTimeoutMs=v;} public long getQuoteTtlSeconds(){return quoteTtlSeconds;} public void setQuoteTtlSeconds(long v){quoteTtlSeconds=v;} public boolean isMockEnabled(){return mockEnabled;} public void setMockEnabled(boolean v){mockEnabled=v;} public boolean isSimulateNoRiders(){return simulateNoRiders;} public void setSimulateNoRiders(boolean v){simulateNoRiders=v;} public Pickup getPickup(){return pickup;} public void setPickup(Pickup v){pickup=v;} public Uber getUber(){return uber;} public void setUber(Uber v){uber=v;} }